import React from 'react';

import PohButton, { ButtonVariant } from '@ui-kit/Button';
import PohInput, { InputTypes } from '@ui-kit/Input';
import PohSelect from '@ui-kit/Select';

import { getWorkoutTypes } from '../@services/workouts.service';
import { IWorkoutType } from '../@types/workouts.types';

const WorkoutsFilterForm = () => {
  const searchParams = new URLSearchParams(location.search);

  const [y, sY] = React.useState(searchParams.get('y'));
  const [d1, sD1] = React.useState(searchParams.get('d1'));
  const [d2, sD2] = React.useState(searchParams.get('d2'));
  const [t, sT] = React.useState(searchParams.get('t'));

  const [types, setTypes] = React.useState<IWorkoutType[]>([]);
  React.useEffect(() => {
    getWorkoutTypes().then(setTypes);
  }, []);

  return (
    <form className="vertical-gapped">
      <PohInput
        name={y ? 'y' : ''}
        horizontal
        label="Годы"
        placeholder={[new Date().getFullYear(), new Date().getFullYear() - 1].join(',')}
        value={y ?? ''}
        onChange={sY}
      />
      <PohInput
        name={d1 ? 'd1' : ''}
        horizontal
        label="Дата от"
        type={InputTypes.date}
        value={d1 ?? ''}
        onChange={sD1}
      />
      <PohInput
        name={d2 ? 'd2' : ''}
        horizontal
        label="Дата до"
        type={InputTypes.date}
        value={d2 ?? ''}
        onChange={sD2}
      />
      <PohSelect<number>
        horizontal
        label="Тип"
        placeholder="Тип тренировки"
        name={t ? 't' : ''}
        id="workout-type"
        allowEmpty
        options={types ? types.map(({ id: value, name }) => ({ label: name, value })) : []}
        disabled={!types}
        value={t ? +t : 0}
        onChange={(v: number) => sT(v.toString())}
      />
      <PohButton type="submit" variant={ButtonVariant.Primary}>
        Фильтровать
      </PohButton>
    </form>
  );
};

export default WorkoutsFilterForm;
