import React from 'react';

import Plus from '@pohodnik/icons/svg/Signs/Plus';
import { useNavigate, useSearchParams } from 'react-router-dom';

import Page from '@components/Page';
import PageHeader from '@components/PageHeader';
import { AuthContext } from '@contexts/AuthContext';
import PohBreadcrumbs from '@ui-kit/Breadcrumb';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohContainer from '@ui-kit/layout/Container';
import { showModal } from '@ui-kit/Modal';

import WorkoutsFilterForm from './WorkoutsFilterForm';
import WorkoutsList from '../components/WorkoutsList';

const WorkoutsMy = () => {
  const navigate = useNavigate();
  const authContext = React.useContext(AuthContext);
  const [searchParams] = useSearchParams();

  const title = React.useMemo(() => {
    const titleParts = ['Мои тренировки'];
    if (searchParams.has('d1')) {
      titleParts.push(`с ${new Date(searchParams.get('d1')!).toLocaleDateString()}`);
    }
    if (searchParams.has('d2')) {
      titleParts.push(`по ${new Date(searchParams.get('d2')!).toLocaleDateString()}`);
    }
    if (searchParams.has('d')) {
      titleParts.push(`за ${new Date(searchParams.get('d')!).toLocaleDateString()}`);
    }

    if (searchParams.has('y')) {
      const formatter = new Intl.ListFormat('default', {
        style: 'long',
        type: 'conjunction',
      });
      titleParts.push(`за ${formatter.format(searchParams.get('y')!.split(','))} г.`);
    }

    return titleParts.join(' ');
  }, [searchParams]);

  return (
    <Page title={title}>
      <PohBreadcrumbs
        data={[
          { href: '/workouts', text: 'Тренировки' },
          { href: '/workouts/my', text: 'Мои тренировки', active: true },
        ]}
      />
      <PohContainer>
        <PageHeader title={title}>
          <PohButton
            icon={IconsEnum.filterOutline}
            onClick={() => {
              showModal({
                children: <WorkoutsFilterForm />,
              });
            }}
          />
          <PohButton
            size={ButtonSize.Small}
            variant={ButtonVariant.Success}
            onClick={() => navigate('/workouts/new')}
          >
            <Plus />
            &nbsp;Добавить<span className="d-none d-sm-inline"> тренировку</span>
          </PohButton>
        </PageHeader>

        <WorkoutsList id_user={authContext.user?.id} batchSize={100000} withTracks />
      </PohContainer>
    </Page>
  );
};

export default WorkoutsMy;
